function parse(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
}
const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, error: row.error || 'Publication jobs could not be loaded.', jobs: [], count: 0 } }];
}
const jobs = parse(row.jobs, []);
return [{ json: { ok: true, jobs: Array.isArray(jobs) ? jobs : [], count: Number(row.count || 0) } }];
